const projects=[["airport-egypt-v2","Airport & Duty Free — Egypt",""],["food-court-dubai","Food Court — Dubai",""],["chalet","Laklouk Resort — Lebanon",""],["restaurant","The Nice Guy Restaurant — Dubai",""],["residential-building-larnaca","Residential Building — Larnaca, Cyprus",""],["contemporary","Private Residence — Greece",""],["garden-pool","Private Villa — Monaco",""],["stone-entry","Private Villa — Monaco",""],["modern-villa","10 Villas Project — Cyprus",""],["classic","Private Residence — Paris",""],["malta","Private Residence — Malta",""],["private-residence-beirut","Private Residence — Beirut, Lebanon",""]];
const grid=document.getElementById('traditional');for(const [id,title,credit] of projects){const b=document.createElement('button');b.className=id==='residential-building-larnaca'?'imagebutton portrait':'imagebutton';b.dataset.image=`assets/${id}.jpg`;const img=document.createElement('img');img.src=b.dataset.image;img.alt=title;img.loading='lazy';const p=document.createElement('p');p.textContent=title;b.append(img,p);if(credit){const s=document.createElement('small');s.textContent=credit;b.append(s);}grid.append(b);}
const modal=document.getElementById('lightbox');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const im=b.querySelector('img');document.getElementById('fullimage').src=b.dataset.image;document.getElementById('fullimage').alt=im.alt;document.getElementById('caption').textContent=im.alt;modal.showModal();}));document.getElementById('close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
